from .scfoperations import SCFOperations


class scf(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    DEFAULT_FAULT_NAME = 'FBB_1815_Not able to synchronize a baseband bus'

    def __init__(self):
        self.scf_operations = SCFOperations()

    def trigger_toggling_in_scf(self, path_to_scf, path_to_new_scf, mnlent_number='1',
                                al_togg_amount=3, al_togg_clearance_time=300,
                                al_togg_condition_time=600,
                                fault_name=DEFAULT_FAULT_NAME, in_use='true'):
        """
        Provides set of functions for toggling in SCF.

        :param path_to_scf: [Mandatory] path to scf which should be modified
        :param path_to_new_scf: [Mandatory] path to save new scf
        :param mnlent_number: [Optional] Number of Distribution Unit (DU). Default is '1'
        :param al_togg_amount: [Optional] the number of times the fault should occur before the toggling occurs,
                               default is '3'.
        :param al_togg_clearance_time: [Optional] the time in after which the fault toggling disappears,
                                       default is '300'.
        :param al_togg_condition_time: [Optional] time in which a given number of faults must appear
                                       in order to toggling activate. Default is '600'.
        :param fault_name: [Optional] name of fault which triggers toggling. Default is 'FBB_1818...'.
        :param in_use: [Optional] describe status of work: 'true' if everything works properly
                       or 'false' if it doesn't work. Default is 'true'.
        """
        return self.scf_operations.toggling_in_scf(path_to_scf, path_to_new_scf,
                                                   mnlent_number=mnlent_number,
                                                   al_togg_amount=al_togg_amount,
                                                   al_togg_clearance_time=al_togg_clearance_time,
                                                   al_togg_condition_time=al_togg_condition_time,
                                                   fault_name=fault_name, in_use=in_use)

    def prepare_scf_file(self, scf_path, should_contain=None, should_not_contain=None):
        """
        Prepares SCF file by ensuring, that entries from should_contain list are present in SCF file and
        entries from should_not_contain list are absent from SCF file.
        Handles following SCF entries: objects, elements, lists with items, lists with simple elements.

        Adding or modifying:
          - object: should_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                         class_name='com.nokia.srbts.tnl:TNL',
                                         version='TNL5G18A_1803_001',
                                         operation='create')]
            Note: parent object (i.e. 'MRBTS-1900') must be specified before it's children (i.e. 'MRBTS-1900/TNLSVC-1')
            in should_contain list.
          - element: should_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                          p_name='neType',
                                          value='FSM')]
          - list with items: should_contain=[dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                  list_name='beamSet',
                                                  items=[dict(basicBeamSet='beamSet_1'),
                                                         dict(basicBeamSet='beamSet_2')])]
          - list with simple elements: should_contain=[dict(dist_name='MRBTS-1900/NRBTS-1/NRCELLGRP-0',
                                                            list_name='nrCellList',
                                                            items=['1', '2'])]
        Removing:
          - object: should_not_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4')]
          - element: should_not_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                              p_name='neType')]
          - list: should_not_contain=[dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                           list_name='beamSet')]

        :param scf_path: path to SCF file which will be prepared, i.e. 'scf_files/SBTS5G18A_5g_pid11.xml'
        :type scf_path: str
        :param should_contain: list of entries which should be present in prepared SCF file
        :type should_contain: list of dicts
        :param should_not_contain: list of entries which should be absent from prepared SCF file
        :type should_not_contain: list of dicts
        """
        return self.scf_operations.prepare_scf_file(scf_path, should_contain, should_not_contain)
